SET search_path=public;
LOCK TABLE information_page_heads,information_page_revisions,information_page_revision_translations,information_page_translation_reviews,information_page_translation_copy_evidence,information_page_publications,information_page_receipts IN ACCESS EXCLUSIVE MODE;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM information_page_revisions) OR EXISTS(SELECT 1 FROM information_page_receipts) OR EXISTS(SELECT 1 FROM information_page_publications) OR EXISTS(SELECT 1 FROM outbox_events WHERE event_type='INFORMATION_PAGE_PUBLICATION_CHANGED') OR EXISTS(SELECT 1 FROM audit_logs WHERE action LIKE 'INFORMATION_PAGE_%') THEN RAISE EXCEPTION 'information page history cannot be downgraded' USING ERRCODE='55000';END IF;END $$;
