DROP INDEX outbox_events_state_transition_unique_idx;
CREATE UNIQUE INDEX outbox_events_state_transition_unique_idx ON outbox_events(event_type,aggregate_type,aggregate_id,aggregate_version) WHERE event_type NOT IN('CONTENT_PUBLICATION_CHANGED','PAYMENT_CONFIG_PUBLISHED','PRICE_BOOK_PUBLISHED');
ALTER TABLE outbox_events DROP CONSTRAINT outbox_events_event_type_check;
ALTER TABLE outbox_events ADD CONSTRAINT outbox_events_event_type_check CHECK(event_type IN('CART_ITEM_ADDED','CONTENT_PUBLICATION_CHANGED','PAYMENT_STATUS_CHANGED','ORDER_PAYMENT_CONFIRMED','REFUND_STATUS_CHANGED','DISPUTE_STATUS_CHANGED','FULFILLMENT_STATUS_CHANGED','NOTIFICATION_REQUESTED','PAYMENT_CONFIG_PUBLISHED','PRICE_BOOK_PUBLISHED'));
ALTER TABLE outbox_events DROP CONSTRAINT outbox_events_aggregate_type_check;
ALTER TABLE outbox_events ADD CONSTRAINT outbox_events_aggregate_type_check CHECK(aggregate_type IN('CART','CONTENT_PUBLICATION','ORDER','PAYMENT_ATTEMPT','REFUND','DISPUTE','FULFILLMENT','NOTIFICATION_DELIVERY','PAYMENT_CONFIG','PRICE_BOOK'));
